import{z as o,x as s,o as t,c as p,q as A,j as i,D as e,d as B,s as r,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"灾难性遗忘的机制","description":"","frontmatter":{"title":"灾难性遗忘的机制","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-forgetting-mechanism.md","filePath":"llm/continual-forgetting-mechanism.md","lastUpdated":1791413859000}'),d={name:"llm/continual-forgetting-mechanism.md"};function m(D,E,h,C,f,_){const l=s("Mermaid");return t(),p("div",null,[E[2]||(E[2]=A('<h1 id="灾难性遗忘的机制" tabindex="-1">灾难性遗忘的机制 <a class="header-anchor" href="#灾难性遗忘的机制" aria-label="Permalink to &quot;灾难性遗忘的机制&quot;">​</a></h1><div class="epigraph"><p>遗忘不是记忆被擦掉，而是新梯度在共享参数上覆盖了旧任务的解；它发生在优化的几何里，不在存储的寿命里。</p><footer>—— 据 McCloskey 与 Cohen 1989、Kirkpatrick 等 2017 整理</footer></div><p><a href="/llm/synthetic-engineering-map">上一课</a>把合成数据工程收束成一张地图：谱系、过滤、域合成到配比与验证，回答的是「一份静态数据配方怎么造出来」。部署之后配方不再静止：新任务与新行为会不断送来要学的东西。本课先钉住这件事为什么难：在一份权重上按顺序学习，新任务的梯度会破坏旧任务的能力，即灾难性遗忘。后课的正则、回放、适配器与合并，都默认你接受「干扰发生在参数空间」这个前提。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>干净的做法是联合训练所有任务的数据，但持续学习的约束是任务按时间到达：\\(T_1\\) 训完，\\(T_2\\) 的数据才来，且 \\(T_1\\) 的数据可能因存储、隐私或成本不再可得。优化问题退化成序列：先把 \\(\\theta\\) 推到 \\(T_1\\) 的解附近，再用 \\(T_2\\) 的梯度继续推。语言模型的各任务共享几乎全部参数，\\(T_2\\) 的下降方向在 \\(T_1\\) 的损失上不为零，往往显著为正——客服风格训完再训代码，客服能力掉了。</p><p><span class="marginnote">可以类比在一张纸上先写满数学笔记、再拿同一支笔写菜谱：菜谱的笔迹会压在笔记上，两边互相干扰。如果每科用一页新纸（独立参数）就没这个问题——但语言模型的参数是共享的「同一张纸」，这正是灾难性遗忘的根源。</span></p><p><a href="/llm/forgetting-metrics">遗忘的度量</a>已把「掉了多少」写成指标：任务 \\(i\\) 刚学完时的成绩 \\(R_{i,i}\\) 与整条序列学完后的 \\(R_{T,i}\\) 之差。本课不重推公式，只回答机制：落差从哪来，为什么有时巨大、有时接近零。</p><h3 id="干扰的三条通路" tabindex="-1">干扰的三条通路 <a class="header-anchor" href="#干扰的三条通路" aria-label="Permalink to &quot;干扰的三条通路&quot;">​</a></h3><p>参数通路：\\(\\theta_1^\\*\\) 是 \\(T_1\\) 损失面的极小点，新梯度把它拉走，旧损失回升。表示通路：前几层被新数据挪动后，旧任务依赖的特征组合整体移位，下游接不上。输出通路：权重变化很小，但格式偏好、拒答边界、模板习惯被新任务改写，旧评测照掉——这一条常被误报成遗忘。</p><p><span class="marginnote">Hardt 等 2016 的稳定性分析给了个对照：学习率越小、步数越节制，两次训练得到的模型越接近。同一支杠杆也控制遗忘——激进的大学习率既伤泛化也伤旧任务。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机制要落到可操作的观察协议。序列训练下，每学完一个任务就在冻结数据上跑一遍所有已见任务的评测，记录成绩轨迹 \\(R_{t,i}\\)。它的价值是把遗忘从「用户投诉」变成曲线：哪一步掉、掉多少、能否被后课的干预救回，都由曲线说话。</p><p>其次做消融定位通路：只改学习率与步数，看遗忘如何随梯度强度变化；只训部分层或低秩增量，看干扰如何随参数范围收缩。语言模型上反复出现的经验是：全参大学习率最烈，低秩小学习率温和得多，<a href="/llm/sft-forgetting">遗忘与原能力保持</a>已给出这条谱系，本课负责解释为什么。</p>',13)),(t(),i(n,null,{default:e(()=>[r(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E4%BB%BB%E5%8A%A1%E6%A2%AF%E5%BA%A6%20g2%22%5D%20--%3E%20SHARED%5B%22%E5%85%B1%E4%BA%AB%E5%8F%82%E6%95%B0%20%CE%B8%22%5D%0A%20%20OLD%5B%22%E6%97%A7%E4%BB%BB%E5%8A%A1%E8%A7%A3%20%CE%B81*%22%5D%20--%3E%20SHARED%0A%20%20SHARED%20--%3E%20Q%7B%22g2%20%E5%9C%A8%E6%97%A7%E6%8D%9F%E5%A4%B1%E4%B8%8A%E7%9A%84%E5%88%86%E9%87%8F%E8%BF%91%E4%BC%BC%E4%B8%BA%E9%9B%B6%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20MOVE%5B%22%E5%8F%82%E6%95%B0%E8%A2%AB%E6%8B%89%E7%A6%BB%E6%97%A7%E8%A7%A3%22%5D%0A%20%20MOVE%20--%3E%20FORGET%5B%22%E6%97%A7%E4%BB%BB%E5%8A%A1%E6%88%90%E7%BB%A9%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20SAFE%5B%22%E6%97%A7%E4%BB%BB%E5%8A%A1%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"参数视角下，遗忘规模由两个几何量决定：新梯度方向落在旧损失在 \\(\\theta_1^\\*\\) 处陡峭方向上的分量有多少，以及沿它走了多少步。把「方向」与「步长」分开，后课的干预点就有了分类：EWC 一族约束方向，回放重混数据。",-1)),E[5]||(E[5]=a("p",null,"表示视角解释遗忘的非线性：小位移可以大破坏，只要挪动了旧任务依赖的关键方向；很多参数各动一点，功能却几乎不变。所以按参数距离度量遗忘会误判，必须按任务成绩度量。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"「小位移大破坏」有个直观例子：只微调嵌入层里几个高频词的向量，参数变化量微不足道，但旧任务若靠这几个词对齐输入，成绩可以整体塌掉；反过来挪动上千个边缘参数，任务可能毫无感觉。所以度量遗忘要看任务成绩，不能看权重挪了多远。")],-1)),E[7]||(E[7]=a("p",null,"输出视角解释一部分假遗忘：只是习惯被改写的情形，提示修复往往比重训便宜，先排除再动参数。",-1)),(t(),i(n,null,{default:e(()=>[r(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%97%A7%E4%BB%BB%E5%8A%A1%E6%88%90%E7%BB%A9%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20D%7B%22%E5%85%88%E5%AE%9A%E4%BD%8D%E6%98%AF%E5%93%AA%E6%9D%A1%E9%80%9A%E8%B7%AF%22%7D%0A%20%20D%20--%3E%7C%22%E8%BE%93%E5%87%BA%E4%B9%A0%E6%83%AF%E8%A2%AB%E6%94%B9%E5%86%99%22%7C%20PR%5B%22%E6%8F%90%E7%A4%BA%E4%BF%AE%E5%A4%8D%3A%E5%85%88%E6%8E%92%E9%99%A4%E5%81%87%E9%81%97%E5%BF%98%22%5D%0A%20%20D%20--%3E%7C%22%E8%A1%A8%E7%A4%BA%E6%BC%82%E7%A7%BB%22%7C%20LR%5B%22%E4%BD%8E%E7%A7%A9%E5%B0%8F%E6%AD%A5%E9%95%BF%3A%E5%8E%8B%E7%BC%A9%E5%8F%82%E6%95%B0%E8%8C%83%E5%9B%B4%22%5D%0A%20%20D%20--%3E%7C%22%E5%8F%82%E6%95%B0%E4%BD%8D%E7%A7%BB%22%7C%20GE%5B%22%E7%9C%8B%E6%96%B9%E5%90%91%E4%B8%8E%E6%AD%A5%E9%95%BF%E4%B8%A4%E4%B8%AA%E5%87%A0%E4%BD%95%E9%87%8F%22%5D%0A%20%20GE%20--%3E%7C%22%E7%BA%A6%E6%9D%9F%E6%96%B9%E5%90%91%22%7C%20EWC%5B%22EWC%20%E4%B8%80%E6%97%8F%E6%AD%A3%E5%88%99%22%5D%0A%20%20GE%20--%3E%7C%22%E9%87%8D%E6%B7%B7%E6%95%B0%E6%8D%AE%22%7C%20RP%5B%22%E5%9B%9E%E6%94%BE%E7%BC%93%E5%86%B2%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=A('<p><span class="marginnote">初学者容易把上线后的任何行为变化都记成「遗忘」。其中一类只是输出习惯被新数据改写——拒答语气、格式模板变了，底层能力还在，换一版提示词就能救回。先做这类便宜的排查再考虑动参数，能省掉大量无谓的重训。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>灾难性遗忘不等于一切能力变化。有些变化是正迁移的代价：删掉过时的接口习惯，本身是收益；把所有变化都当损失，持续学习会退化成拒绝学习。</p><p>只要旧数据还能回收，重训总是兜底方案；持续学习研究的真正前提是旧数据不可得或太贵，前提不成立的系统，先修<a href="/llm/training-replay">训练重放与可复现</a>的重训管线可能更便宜。规模也改变问题：模型越大、新任务越浅，遗忘越轻——不是机制消失，而是任务只扰动了浅层。最后，真实流里「任务」常无清晰边界，下一课的机制在任务定义模糊时会进一步打折。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持续学习的难点是序列约束：旧数据不可得，联合训练不可行，梯度在共享参数上互相覆盖。</li><li>干扰有三条通路：参数位移、表示漂移、输出习惯偏移；只有任务成绩轨迹能可靠度量。</li><li>遗忘规模由新梯度在旧损失陡峭方向的分量与步数共同决定，由此给后课的干预点分类。</li><li>参数距离会误判：小位移可以大破坏，大位移可以无损伤。</li><li>先排除输出习惯被改写的假遗忘，再谈参数级干预。</li><li>出处：McCloskey 与 Cohen 1989 的干扰实验；Kirkpatrick 等 2017 的 EWC 框架；Hardt 等 2016 的稳定性分析。</li></ul>',6))])}const g=o(d,[["render",m]]);export{c as __pageData,g as default};
